import { cookies } from "next/headers"
import { toggleNotifications } from "./actions"

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get("notifications")?.value === "on"

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications: <strong>{enabled ? "On" : "Off"}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          {enabled ? "Turn notifications off" : "Turn notifications on"}
        </button>
      </form>
    </main>
  )
}

